from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parent.parent
D=ROOT/'dist'
base='https://ciencias.bogota.unal.edu.co/'
OAN=base+'departamentos_e_Institutos/observatorio_astronomico_nacional/'
DIR=base+'directorio_docente/observatorio_astronomico_nacional/'
